-- Bazaarly application database dump (synthetic). Generated for the book.

DROP TABLE IF EXISTS `bz_users`;
CREATE TABLE `bz_users` (`user_id` VARCHAR(500), `email` VARCHAR(500), `created_at` VARCHAR(500), `status` VARCHAR(500));

DROP TABLE IF EXISTS `bz_user_details`;
CREATE TABLE `bz_user_details` (`user_id` VARCHAR(500), `first_name` VARCHAR(500), `last_name` VARCHAR(500), `phone` VARCHAR(500), `birth_year` VARCHAR(500));

DROP TABLE IF EXISTS `bz_user_addresses`;
CREATE TABLE `bz_user_addresses` (`address_id` VARCHAR(500), `user_id` VARCHAR(500), `address_type` VARCHAR(500), `street` VARCHAR(500), `city_id` VARCHAR(500), `zip_code` VARCHAR(500), `is_default` VARCHAR(500));

DROP TABLE IF EXISTS `bz_cities`;
CREATE TABLE `bz_cities` (`city_id` VARCHAR(500), `city_name` VARCHAR(500), `state` VARCHAR(500), `country` VARCHAR(500), `region` VARCHAR(500));

DROP TABLE IF EXISTS `bz_states`;
CREATE TABLE `bz_states` (`state_code` VARCHAR(500), `state_name` VARCHAR(500), `region` VARCHAR(500), `country` VARCHAR(500));

DROP TABLE IF EXISTS `bz_sellers`;
CREATE TABLE `bz_sellers` (`seller_id` VARCHAR(500), `seller_name` VARCHAR(500), `commission_rate` VARCHAR(500), `country` VARCHAR(500), `joined_at` VARCHAR(500));

DROP TABLE IF EXISTS `bz_products`;
CREATE TABLE `bz_products` (`product_code` VARCHAR(500), `product_name` VARCHAR(500), `brand` VARCHAR(500), `category` VARCHAR(500), `subcategory` VARCHAR(500), `upc` VARCHAR(500), `price` VARCHAR(500), `hash_key` VARCHAR(500), `source_id` VARCHAR(500), `legacy_flag` VARCHAR(500));
